    "aspect_ratio": "1:1",
    "size": "square"
  },
  "layout": {
    "grid": "2x2",
    "panels": [
      {
        "position": "top-left",
        "theme": "Anxiety and self-doubt",
        "background": "A soft pink and white female-centric lifestyle scene, with a blurred effect and light and shadow textures.",
        "subject": "Close-up: A young woman wearing a comfortable white knit sweater, one hand close to her face, her hair tied in a messy bun, partially obscuring her face.",
        "text_blocks": [
          {
            "text": "You're missing out if you don't know this!",
            "style": "Yellow diagonal banner with black text",
            "position": "top-left"
