            "position": "below main headline"
          },
          {
            "text": "Feeling irritable for no reason",
            "style": "The checklist items within the white rounded boxes have red checkmark icons."
          },
          {
            "text": "Despite working very hard, nothing has changed.",
            "style": "The checklist items within the white rounded boxes have red checkmark icons."
          },
          {
            "text": "Not understanding one's own true thoughts",
            "style": "The checklist items within the white rounded boxes have red checkmark icons."
          },
          {
            "text": "Interpersonal relationships are exhausting",
            "style": "The checklist items within the white rounded boxes have red checkmark icons."
          },
          {
            "text": "Feeling incredibly uneasy about the future",
            "style": "The checklist items within the white rounded boxes have red checkmark icons."
          },
          {
            "text": "Those troubles don't have to be borne alone.",
            "style": "Pink round badge with white text",
            "position": "lower-right"
          }
        ],
        "count": 9
      },
      {
        "position": "top-right",
        "theme": "Not a cure, but a mechanism of change.",
        "background": "The deep cosmic galaxies, nebulae tinged with blue, purple, and magenta, starbursts, energy vortexes, and a luminous spiritual atmosphere.",
        "subject": "A small female silhouette, either from behind or in profile, stands beside a glowing entrance or pillar of light, her face partially obscured.",
        "text_blocks": [
          {
            "text": "It looks ordinary, but actually...",
            "style": "White text on a black diagonal banner",
            "position": "top-left"
          },
          {
            "text": "this,",
            "style": "Large white text",
            "position": "upper-left"
          },
          {
            "text": "no",
            "style": "Oversized yellow text in deep purple strokes",
            "position": "center"
          },
          {
            "text": "cure.",
            "style": "Large white text",
            "position": "below"
          },
          {
            "text": "By \"adjusting\"",
            "style": "Text within white box",
            "position": "lower-left"
          },
          {
            "text": "Reality will change.",
            "style": "Pink highlighted text",
            "position": "mid-lower-left"
          },
          {
            "text": "The mechanism has been found!",
            "style": "White text",
            "position": "bottom-left"
          }
        ],
        "graphic_elements": [
          {
            "type": "Curved yellow arrow",
            "count": 1,
            "direction": "Pointing to the glowing figure"
          }
        ],
        "count": 8
      },
      {
        "position": "bottom-left",
        "theme": "Returning to your true self to create a better future",
        "background": "A bright blue sky with soft clouds, green fields, floating leaves, and a bright, hopeful daytime atmosphere.",
        "subject": "A cheerful young woman in a sleeveless white dress, arms outstretched, twirls in the sunlight, her face partially obscured.",
        "text_blocks": [
          {
            "text": "After returning to one's true self",
            "style": "Red and black color scheme title",
            "position": "top"
          },
          {
            "text": "Will usher in",
            "style": "Oversized gold gradient title",
            "position": "center"
          },
          {
            "text": "Such a future",
            "style": "Large black text",
            "position": "right-center"
          },
          {
            "text": "My mind became lighter, and every day was filled with joy.",
            "style": "The reward items inside the white rounded bubble are marked with a pink heart icon."
          },
          {
            "text": "Interpersonal relationships become smooth and filled with love.",
            "style": "The reward items inside the white rounded bubble are marked with green crowd icons."
          },
          {
            "text": "When the flow of money changes, wealth naturally flows in.",
            "style": "The earnings item inside the white rounded bubble has a gold yen icon."
          },
          {
            "text": "Your life is about to change beyond your wildest imagination!",
            "style": "Pink ribbon at the bottom, white text",
            "position": "bottom"
          }
        ],
        "count": 7
      },
      {
        "position": "bottom-right",
        "theme": "Limited-time discount",
        "background": "Explosive textures in fiery red and gold, with glitter and sparkling trails, a luxurious and urgent aesthetic.",
        "text_blocks": [
          {
            "text": "If you don't know",
            "style": "Yellow brushstrokes on the banner, black text",
            "position": "top-left"
          },
          {
            "text": "What a loss!",
            "style": "Extra-large gold Chinese characters with a metallic bevel effect",
            "position": "upper-right"
          },
          {
            "text": "The usual price is 9,980 yen (tax included).",
            "style": "White price tag with crossed-out black numbers and small print tax information.",
            "position": "upper-left"
          },
          {
            "text": "Trial price",
            "style": "White text",
            "position": "center-left"
          },
          {
            "text": "40% off",
            "style": "Huge pink to white gradient discount text",
            "position": "center-lower"
          },
          {
            "text": "Limited time offer! Limited recruitment! Only a few spots available.",
            "style": "Gold round seal badge",
            "position": "right-center"
          },
          {
            "text": "Please see my profile for details.",
            "style": "Purple action call bar, white text and white arrow button",
            "position": "bottom"
          }
        ],
        "count": 7
      }
    ],
    "total_panels": 4
  },
  "composition": "A busy and persuasive Japanese advertising mosaic, optimized for social media thumbnail visibility, with each quadrant featuring a unique emotional message and color scheme, and making extensive use of diagonal banners, oversized kanji and numbers, glossy badges, rounded white information boxes, and dramatic lighting effects.",
  "customization": {
    "primary headline": "{argument name=\"headline text\" default=\"99% of people are wrong\"}",
    "discount text": "{argument name=\"discount text\" default=\"40% off\"}",
    "price": "{argument name=\"price\" default=\"9,980 yen (tax included)\"}",
    "main color palette": "{argument name=\"main color palette\" default=\"Pink, blue-purple galaxies, sky blue, red-gold\"}",
    "call to action": "{argument name=\"call to action\" default=\"Please see my profile for details.\"}"
  },
  "render_notes": "Ensure all Japanese text is large and clear, with layered shadows and outlines; use a sophisticated, composite advertising aesthetic rather than minimalist design; faces should be blurred or partially obscured; emphasize the emotional contrast between anxiety, revelation, a shift in hope, and the urgent offer."
}

